// El reloj sube el WAV mientras graba (sin saber el largo final: lo manda en 0xFFFFFFFF).
// Acá se corrige el largo y se le pone nombre y tipo para que Groq lo reconozca.
const item = $input.first();
const buf = Buffer.from(await this.helpers.getBinaryDataBuffer(0, 'audio'));
if (buf.length >= 44 && buf.toString('ascii', 0, 4) === 'RIFF') {
  buf.writeUInt32LE(buf.length - 8, 4);
  buf.writeUInt32LE(buf.length - 44, 40);
}
item.binary.audio = await this.helpers.prepareBinaryData(buf, 'pregunta.wav', 'audio/wav');
return [item];

// Texto para la pantalla del reloj: solo ASCII (la letra del reloj no tiene tildes ni ñ)
// y corto, porque va en los encabezados X-Pregunta / X-Respuesta.
const ascii = (s) => String(s || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^\x20-\x7E]/g, '').replace(/\s+/g, ' ').trim();
const pregunta = ascii($('Voz a texto').first().json.text).slice(0, 150);
const respuesta = ascii($('JARVIS').first().json.output || 'No pude responder.').slice(0, 390);

// Órdenes para el reloj: cada herramienta del reloj devuelve "ACCION:ALARMA 07:00 - ...".
// Se juntan en el encabezado X-Accion ("ALARMA 07:00;TIMER 600") y el reloj las ejecuta.
const pasos = JSON.stringify($('JARVIS').first().json.intermediateSteps || []);
const accion = [...pasos.matchAll(/ACCION:([A-Z]+ [A-Z0-9:]+)/g)].map((m) => m[1]).join(';');

// Voz: n8n-flujos/voz.mjs (Piper, voz Sharvard; si falla, la de Windows) la deja en base64,
// PCM mono de 16 bits a 24 kHz (lo que espera el reloj). Si no hubo voz, un silencio cortito.
let b64 = '';
try { b64 = $('Voz').first().json.stdout.trim(); } catch (e) {}
if (!b64) b64 = Buffer.alloc(2).toString('base64');

return [{
  json: { pregunta, respuesta, accion },
  binary: { voz: { data: b64, mimeType: 'application/octet-stream', fileName: 'respuesta.pcm' } },
}];

const s = Math.round(Number(query.minutos) * 60);
if (!(s > 0)) return 'No entendi la duracion';
return `ACCION:TIMER ${s} - listo, temporizador de ${query.minutos} min andando en el reloj`;

const ok = { iniciar: 'INICIAR', pausar: 'PAUSAR', reset: 'RESET' };
const a = ok[String(query.accion).toLowerCase()];
if (!a) return 'Accion invalida: usa iniciar, pausar o reset';
return `ACCION:CRONO ${a} - listo, cronometro (${query.accion}) en el reloj`;
